/* ═══════════════════════════════════════════════════════════════════════════
   SCORING ENGINE  ─  multi-factor weighted compatibility
   ═══════════════════════════════════════════════════════════════════════════ */
const clamp = (n) => Math.max(0, Math.min(100, n));

/* Detect behavioral patterns from the log */
function detectBehaviorPatterns(log) {
  const patterns = {
    riskTaker: 0, collaborator: 0, analyticalDecider: 0,
    creativeRisk: 0, empathyDriven: 0, speedOriented: 0,
  };
  log.forEach(({ e }) => {
    if ((e.risk || 0) > 5) patterns.riskTaker++;
    if ((e.communication || 0) > 5 && (e.leadership || 0) > 3) patterns.collaborator++;
    if ((e.analytical || 0) > 5 && (e.logic || 0) > 3) patterns.analyticalDecider++;
    if ((e.creativity || 0) > 5 && (e.risk || 0) > 3) patterns.creativeRisk++;
    if ((e.communication || 0) > 6) patterns.empathyDriven++;
  });
  return patterns;
}

/* Detect learning style */
function detectLearningStyle(profile) {
  const { analytical, creativity, logic, communication } = profile;
  if (analytical > 75 && logic > 75) return "Systems learner — you absorb frameworks, then fill in detail";
  if (creativity > 75 && communication > 70) return "Narrative learner — you learn through stories, examples and conversation";
  if (logic > 78 && analytical > 70) return "First-principles learner — you work from ground up, questioning assumptions";
  return "Adaptive learner — you flex between conceptual and hands-on approaches";
}

/* Detect leadership style */
function detectLeadershipStyle(profile, patterns) {
  const { leadership, communication, analytical, risk } = profile;
  if (leadership > 78 && risk > 70) return "Bold, decisive leader — you move fast and rally others behind a vision";
  if (leadership > 70 && communication > 78) return "Collaborative leader — you build consensus and make people feel heard";
  if (analytical > 78 && leadership > 60) return "Analytical leader — you lead with data, not instinct";
  if (leadership < 55) return "Specialist contributor — you lead through expertise rather than hierarchy";
  return "Situational leader — you adapt your style to what the moment needs";
}

/* Full career scoring */
function scoreCareer(profile, interestW, career) {
  // Trait fit (weighted — key traits 2.4x)
  let totalW = 0, acc = 0;
  TRAITS.forEach((t) => {
    const w = career.key.includes(t) ? 2.4 : 1;
    acc += (100 - Math.abs(profile[t] - career.ideal[t])) * w;
    totalW += w;
  });
  const traitFit = clamp(acc / totalW);

  // Interest fit
  const totalInterest = Object.values(interestW).reduce((a, b) => a + b, 0) || 1;
  const matched = career.interests.reduce((s, k) => s + (interestW[k] || 0), 0);
  const interestFit = clamp((matched / totalInterest) * 140);

  // Industry bonus — careers matching dominant interest areas score higher
  const industryBonus = career.industryFit
    ? career.industryFit.reduce((s, ind) => {
        const relatedInterests = { Technology: "Tech", Healthcare: "Medical", Finance: "Business", Business: "Business", Marketing: "Business", Design: "Arts", Engineering: "STEM", Education: "Arts", Research: "STEM", Media: "Arts", Law: "Business", Entrepreneurship: "Business" };
        const rel = relatedInterests[ind];
        return s + (rel ? (interestW[rel] || 0) * 0.3 : 0);
      }, 0)
    : 0;

  const raw = 0.68 * traitFit + 0.24 * interestFit + 0.08 * clamp(industryBonus * 5);
  return Math.round(clamp(raw));
}

/* Confidence score — how certain we are, based on number of choices made */
function calcConfidence(log, profile) {
  const totalChoices = log.length;
  const profileVariance = TRAITS.reduce((v, t) => v + Math.abs(profile[t] - 50), 0) / TRAITS.length;
  const base = Math.min(totalChoices / 31, 1); // max 31 data points (7+12+12)
  const signal = Math.min(profileVariance / 30, 1);
  return Math.round(clamp((base * 0.6 + signal * 0.4) * 100));
}

/* Detect work style */
function detectWorkStyle(profile) {
  const { analytical, creativity, leadership, communication, risk } = profile;
  const tags = [];
  if (analytical > 72 && risk < 55) tags.push("structured and methodical");
  if (creativity > 72 && risk > 60) tags.push("experimental and idea-driven");
  if (leadership > 72 && communication > 70) tags.push("collaborative and team-oriented");
  if (analytical > 75 && communication < 55) tags.push("independent deep-focus work");
  if (risk > 75) tags.push("ambiguity-tolerant and entrepreneurial");
  if (communication > 80) tags.push("people-centric and relationship-building");
  return tags.length ? tags.join(", ") : "flexible and context-adaptive";
}

/* Detect personality archetype */
function detectPersonaArchetype(strengths) {
  const labelMap = {
    "analytical|logic": "The Analytical Builder",
    "logic|analytical": "The Analytical Builder",
    "creativity|communication": "The Creative Communicator",
    "communication|creativity": "The Creative Communicator",
    "leadership|communication": "The Natural Leader",
    "communication|leadership": "The Natural Leader",
    "risk|leadership": "The Bold Visionary",
    "leadership|risk": "The Bold Visionary",
    "creativity|risk": "The Maverick Maker",
    "risk|creativity": "The Maverick Maker",
    "analytical|communication": "The Strategic Connector",
    "communication|analytical": "The Strategic Connector",
    "logic|creativity": "The Inventive Reasoner",
    "creativity|logic": "The Inventive Reasoner",
    "leadership|analytical": "The Decisive Strategist",
    "analytical|leadership": "The Decisive Strategist",
    "risk|communication": "The Charismatic Gambler",
    "communication|risk": "The Charismatic Gambler",
  };
  return labelMap[`${strengths[0]}|${strengths[1]}`] || `The ${TRAIT_LABEL[strengths[0]]} Type`;
}

/* Score industry fit */
function scoreIndustry(profile, interestW, industryName) {
  const relatedCareers = CAREERS.filter(c => c.industryFit && c.industryFit.includes(industryName));
  if (!relatedCareers.length) return 0;
  const avg = relatedCareers.reduce((s, c) => s + scoreCareer(profile, interestW, c), 0) / relatedCareers.length;
  return Math.round(clamp(avg));
}

/* Full report builder */
function buildReport(profile, interestW, log) {
  const ranked = CAREERS
    .map((c) => ({ ...c, match: scoreCareer(profile, interestW, c), confidence: calcConfidence(log, profile) }))
    .sort((a, b) => b.match - a.match);

  const top10 = ranked.slice(0, 10);
  const top = ranked[0];
  const backups = ranked.slice(1, 3);

  const sorted = [...TRAITS].sort((a, b) => profile[b] - profile[a]);
  const strengths = sorted.slice(0, 2);
  const growth = sorted.slice(-2).reverse();
  const allStrengths = sorted.slice(0, 3);
  const allGrowth = sorted.slice(-3).reverse();

  // Evidence-based reasons
  const reasons = log
    .map((e) => ({ why: e.why, boost: top.key.reduce((s, t) => s + (e.e[t] || 0), 0) }))
    .filter((r) => r.boost > 0)
    .sort((a, b) => b.boost - a.boost)
    .slice(0, 4)
    .map((r) => r.why);

  const persona = detectPersonaArchetype(strengths);
  const patterns = detectBehaviorPatterns(log);
  const learningStyle = detectLearningStyle(profile);
  const leadershipStyle = detectLeadershipStyle(profile, patterns);
  const workStyle = detectWorkStyle(profile);
  const confidence = calcConfidence(log, profile);

  // Industry scores
  const industryScores = INDUSTRIES.map(ind => ({
    ...ind,
    score: scoreIndustry(profile, interestW, ind.name),
    topCareer: (CAREERS.filter(c => c.industryFit?.includes(ind.name)).sort((a,b) => scoreCareer(profile,interestW,b) - scoreCareer(profile,interestW,a))[0]?.name) || "",
  })).sort((a, b) => b.score - a.score);

  // Communication style detection
  const commStyle = profile.communication > 78
    ? "Direct and expressive — you lead conversations and articulate ideas with confidence"
    : profile.communication > 60
    ? "Measured and thoughtful — you communicate clearly but prefer listening to speaking"
    : "Concise and written-focused — you express your best thinking through structured output";

  // Decision making style
  const decisionStyle = (profile.analytical > 72 && profile.logic > 70)
    ? "Data-driven — you want evidence before you commit"
    : (profile.risk > 72 && profile.leadership > 65)
    ? "Intuitive and bold — you trust your gut and act fast"
    : "Collaborative — you gather input and build consensus before deciding";

  // Problem solving style
  const problemStyle = profile.analytical > 75
    ? "Systematic decomposition — you break complex problems into structured parts"
    : profile.creativity > 78
    ? "Lateral thinking — you reframe problems and find unexpected solutions"
    : "Pragmatic — you go with what works, iterating quickly";

  return {
    top, backups, top10, strengths, growth, allStrengths, allGrowth,
    reasons, persona, patterns, learningStyle, leadershipStyle, workStyle,
    commStyle, decisionStyle, problemStyle, confidence, industryScores,
  };
}

