/* ═══════════════════════════════════════════════════════════════════════════
   IMPROVEMENT PLAN GENERATORS
   ═══════════════════════════════════════════════════════════════════════════ */
function buildPlan30(report, profile) {
  const items = [];
  const top = report.top.name;
  items.push(`Research what a day in the life of a ${top} actually looks like — not the job description, the reality.`);
  items.push(`Find and follow 3 people currently working in ${top.toLowerCase().includes("engineer") || top.toLowerCase().includes("data") || top.toLowerCase().includes("ai") ? "tech/engineering" : top.toLowerCase().includes("doctor") || top.toLowerCase().includes("pharma") || top.toLowerCase().includes("dent") ? "healthcare" : "your target field"} on LinkedIn.`);
  if (profile.communication < 60) items.push("Write one short opinion piece per week — practice articulating your thoughts clearly.");
  if (profile.analytical < 60) items.push("Work through one logic puzzle or case study daily to sharpen structured thinking.");
  if (profile.creativity < 60) items.push("Spend 20 minutes each day exploring a field completely unrelated to your studies.");
  items.push(`Identify one gap between your current skills and what ${top} requires — and make a plan to close it.`);
  return items.slice(0, 4);
}

function buildPlan6m(report, profile) {
  const items = [];
  const top = report.top.name;
  const istech = ["Software Engineer","AI / ML Engineer","Cybersecurity Specialist","Product Manager","Data Scientist"].includes(top);
  const ismed = ["Doctor / Surgeon","Pharmacist","Psychologist / Therapist","Dentist"].includes(top);
  const isbiz = ["Entrepreneur / Founder","Business Analyst","Investment Banker","Financial Analyst","HR Manager / People Lead"].includes(top);

  if (istech) items.push("Complete one online technical course in your target domain (CS50, Python for Everyone, Google Data Analytics, etc.).");
  else if (ismed) items.push("Arrange a hospital or clinic attachment — observe professionals in your target specialty.");
  else if (isbiz) items.push("Run a small real project: sell something, manage a budget, or lead a team initiative.");
  else items.push("Build one portfolio piece directly relevant to your target career.");

  if (profile.leadership < 65) items.push("Take on a leadership role in a club, event, or group — formal title optional.");
  items.push("Have at least 2 informational interviews with people in careers from your top 3 matches.");
  items.push(`Narrow your degree shortlist to 3 specific programmes. Compare ${report.top.degrees.slice(0,2).join(" vs ")}.`);
  items.push(`Address your growth area in ${report.allGrowth[0]} through a focused course, book, or practice routine.`);
  return items.slice(0, 4);
}

function buildPlan3y(report, profile) {
  const items = [];
  const top = report.top.name;
  items.push(`Complete your undergraduate degree in a field aligned with ${top} — pick a programme with strong industry connections.`);
  items.push("Build a portfolio of 3–5 real projects, internships, or experiences that demonstrate competency in your field.");
  items.push("Develop your secondary skillset: the top professionals in most fields are T-shaped — deep in one area, literate across others.");
  if (profile.risk < 55) items.push("Build your comfort with calculated risk — take on at least one project outside your comfort zone each year.");
  items.push(`Aim for your first relevant internship or part-time role within 18 months. The job market rewards people who started early.`);
  items.push("Build a personal brand in your field — write, speak, or share work publicly. This compounds over years.");
  return items.slice(0, 5);
}

/* ═══════════════════════════════════════════════════════════════════════════
   LEARNING ROADMAP GENERATOR
   ═══════════════════════════════════════════════════════════════════════════ */
function buildLearningRoadmap(report, profile) {
  const top = report.top.name;
  const istech = top.toLowerCase().includes("engineer") || top.toLowerCase().includes("data") || top.toLowerCase().includes("ai") || top.toLowerCase().includes("cyber") || top.toLowerCase().includes("product");
  const ismed = ["Doctor / Surgeon","Pharmacist","Psychologist / Therapist","Dentist"].includes(top);
  const iscreative = ["Graphic Designer","UX / UI Designer","Architect","Content Creator / Influencer","Brand / Marketing Strategist"].includes(top);
  const isfinance = ["Investment Banker","Financial Analyst","Business Analyst"].includes(top);

  const immediateSkills = istech
    ? ["Python or JavaScript basics", "SQL fundamentals", "Version control (Git)", "Problem-solving practice (LeetCode easy)"]
    : ismed
    ? ["Biology & chemistry foundations", "Medical terminology", "Clinical observation skills", "Research paper reading habits"]
    : iscreative
    ? ["Design fundamentals", "Figma or Adobe basics", "Visual composition theory", "Portfolio building"]
    : isfinance
    ? ["Excel / Sheets mastery", "Financial statement reading", "Basic accounting principles", "Data analysis fundamentals"]
    : ["Communication & writing", "Critical thinking", "Research methodology", "Presentation skills"];

  const nextSkills = istech
    ? ["System design concepts", "Cloud platforms (AWS/GCP basics)", "Data structures & algorithms", "APIs & integration"]
    : ismed
    ? ["Anatomy & physiology deep dive", "Pathology foundations", "Patient communication", "Research methodology"]
    : iscreative
    ? ["UX research methods", "Brand strategy", "Motion & interaction design", "Client management"]
    : isfinance
    ? ["Financial modelling", "Valuation methods", "Power BI / Tableau", "Industry-specific knowledge"]
    : ["Project management", "Leadership fundamentals", "Domain-specific tools", "Networking & personal brand"];

  const certifications = istech
    ? ["Google IT Support Certificate", "AWS Cloud Practitioner", "Google Data Analytics", "Meta Front-End Developer"]
    : ismed
    ? ["First Aid & CPR", "Medical ethics coursework", "Research assistant certification", "Pre-med shadow programmes"]
    : iscreative
    ? ["Google UX Design Certificate", "Adobe Certified Professional", "HubSpot Content Marketing", "Canva Design School"]
    : isfinance
    ? ["Bloomberg Market Concepts", "CFA Level 1 (in time)", "Financial Modelling & Valuation Analyst (FMVA)", "Excel Expert"]
    : ["PMP Foundation", "Google Project Management", "HubSpot certifications", "LinkedIn Learning paths"];

  return [
    { phase: "Immediate Skills (Build Now)", color: "#39E0C4", items: immediateSkills },
    { phase: "Next Skills (6–18 Months)", color: "#6C8BFF", items: nextSkills },
    { phase: "Recommended Certifications", color: "#FFC56B", items: certifications },
  ];
}
